"use client";

import * as React from "react";

import { cn } from "@/lib/utils";
import { useVisualViewport } from "@/hooks/use-visual-viewport";

export type KeyboardAvoidingViewProps = React.ComponentPropsWithoutRef<"div"> & {
  behavior?: "padding" | "height" | "position";
  keyboardOffset?: number;
};

export function KeyboardAvoidingView({
  behavior = "padding",
  keyboardOffset = 0,
  className,
  style,
  ...props
}: KeyboardAvoidingViewProps) {
  const viewport = useVisualViewport();
  const keyboardHeight = Math.max(0, viewport.keyboardHeight - keyboardOffset);
  const variables = {
    "--pwa-keyboard-height": `${keyboardHeight}px`,
    "--pwa-visual-viewport-height": viewport.height ? `${viewport.height}px` : "100dvh",
  } as React.CSSProperties;

  const behaviorStyle: React.CSSProperties =
    behavior === "height"
      ? { height: "var(--pwa-visual-viewport-height, 100dvh)" }
      : behavior === "position"
        ? { transform: "translateY(calc(var(--pwa-keyboard-height, 0px) * -1))" }
        : { paddingBottom: "var(--pwa-keyboard-height, 0px)" };

  return (
    <div
      data-keyboard-open={keyboardHeight > 0 ? "" : undefined}
      data-slot="keyboard-avoiding-view"
      className={cn("transition-[height,padding,transform] duration-200", className)}
      style={{ ...variables, ...behaviorStyle, ...style }}
      {...props}
    />
  );
}

"use client";

import * as React from "react";

export type VisualViewportState = {
  width: number;
  height: number;
  offsetTop: number;
  offsetLeft: number;
  scale: number;
  keyboardHeight: number;
  supported: boolean;
};

const serverState: VisualViewportState = {
  width: 0,
  height: 0,
  offsetTop: 0,
  offsetLeft: 0,
  scale: 1,
  keyboardHeight: 0,
  supported: false,
};

function readViewport(): VisualViewportState {
  if (typeof window === "undefined") return serverState;

  const viewport = window.visualViewport;
  if (!viewport) {
    return {
      width: window.innerWidth,
      height: window.innerHeight,
      offsetTop: 0,
      offsetLeft: 0,
      scale: 1,
      keyboardHeight: 0,
      supported: false,
    };
  }

  const keyboardHeight = Math.max(
    0,
    window.innerHeight - viewport.height - viewport.offsetTop,
  );

  return {
    width: viewport.width,
    height: viewport.height,
    offsetTop: viewport.offsetTop,
    offsetLeft: viewport.offsetLeft,
    scale: viewport.scale,
    keyboardHeight: keyboardHeight > 80 ? keyboardHeight : 0,
    supported: true,
  };
}

export function useVisualViewport(): VisualViewportState {
  const [state, setState] = React.useState<VisualViewportState>(serverState);

  React.useEffect(() => {
    const viewport = window.visualViewport;
    let frame = 0;
    const update = () => {
      window.cancelAnimationFrame(frame);
      frame = window.requestAnimationFrame(() => setState(readViewport()));
    };

    update();
    viewport?.addEventListener("resize", update);
    viewport?.addEventListener("scroll", update);
    window.addEventListener("resize", update);
    window.addEventListener("orientationchange", update);

    return () => {
      window.cancelAnimationFrame(frame);
      viewport?.removeEventListener("resize", update);
      viewport?.removeEventListener("scroll", update);
      window.removeEventListener("resize", update);
      window.removeEventListener("orientationchange", update);
    };
  }, []);

  return state;
}
